begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000004301','frozen-ingredients@example.test');
create temp table frozen_state(name text primary key,value bigint);
insert into frozen_state values('recipe',(select row_id from public.meals where app_id='meal-korean-beef-bowl'));
insert into frozen_state values('food',(select food_row_id from public.meal_ingredients where meal_row_id=(select value from frozen_state where name='recipe') order by ingredient_order limit 1));
insert into frozen_state values('revision',(select revision from public.meals where row_id=(select value from frozen_state where name='recipe')));
insert into public.food_serving_options(food_row_id,label,unit,grams,provider_revision) values((select value from frozen_state where name='food'),'Frozen test spoon','tbsp',12,'frozen-test');
insert into frozen_state values('copy',private.cooking_copy_recipe((select value from frozen_state where name='recipe'),'00000000-0000-0000-0000-000000004301'));
select ok(not exists(select 1 from public.meal_ingredients i join public.foods f on f.row_id=i.food_row_id where i.meal_row_id=(select value from frozen_state where name='copy') and f.is_system),'all catalog dependencies become owned immutable food copies');
insert into frozen_state values('copy-food',(select food_row_id from public.meal_ingredients where meal_row_id=(select value from frozen_state where name='copy') order by ingredient_order limit 1));
select is((select calories from public.foods where row_id=(select value from frozen_state where name='food')),(select calories from public.foods where row_id=(select value from frozen_state where name='copy-food')),'frozen food retains exact source calories');
select is((select snapshot_fdc_id from public.foods where row_id=(select value from frozen_state where name='copy-food')),(select fdc_id from public.foods where row_id=(select value from frozen_state where name='food')),'frozen food retains its original provider identifier');
select is((select count(*) from public.food_serving_options where food_row_id=(select value from frozen_state where name='copy-food') and label='Frozen test spoon' and grams=12),1::bigint,'trusted conversions are copied');
select is(private.cooking_copy_recipe((select value from frozen_state where name='recipe'),'00000000-0000-0000-0000-000000004301'),(select value from frozen_state where name='copy'),'unchanged recipe snapshot is reused');
update public.foods set calories=calories+10 where row_id=(select value from frozen_state where name='food');
select is((select revision::bigint from public.meals where row_id=(select value from frozen_state where name='recipe')),(select value+1 from frozen_state where name='revision'),'changed food basis advances live recipe revision');
select is((select calories from public.foods where row_id=(select value from frozen_state where name='food'))-10,(select calories from public.foods where row_id=(select value from frozen_state where name='copy-food')),'source changes do not rewrite retained nutrition');
select isnt(private.cooking_copy_recipe((select value from frozen_state where name='recipe'),'00000000-0000-0000-0000-000000004301'),(select value from frozen_state where name='copy'),'new source basis produces a separate recipe snapshot');
select throws_ok($$update public.foods set calories=0 where row_id=(select value from frozen_state where name='copy-food')$$,'P0001',null,'retained food copy cannot be edited');
select * from finish();
rollback;
